    d = 0
    reset = 0
    out = []
    for row in vectors:
        if 'd' in row:
            d = row['d'] & 0xFF
        if 'reset' in row:
            reset = row['reset'] & 1
        if reset:
            q = 0x34
        else:
            q = d & 0xFF
        out.append({'q': q})
        if 'mid' in row:
            mid = row['mid']
